export async function verifyNativeCompanyReports({db,profile,revision,secret}){
 const keys=['JWT_SECRET','MWS_STORE_LIFECYCLE_PROFILE','RENDER_GIT_COMMIT','BACKUP_MONITOR_SECRET'],saved=Object.fromEntries(keys.map(k=>[k,process.env[k]]));Object.assign(process.env,{JWT_SECRET:'isolated-native-company-reports-secret',MWS_STORE_LIFECYCLE_PROFILE:`BACKOFFICE_COMPANY_${profile}_V1`,RENDER_GIT_COMMIT:revision,BACKUP_MONITOR_SECRET:secret});
 const mutate=(sql,...values)=>db.$transaction(async tx=>{await tx.$queryRawUnsafe("SELECT set_config('mws.lifecycle_generations',$1,true)",JSON.stringify({selected:'7',sibling:'0',foreign:'0'}));return tx.$executeRawUnsafe(sql,...values)});
 let server;
 try{
  await mutate('UPDATE "CompanyModule" SET "active"=true WHERE "companyId"=\'company\' AND "moduleKey"=\'INVENTORY\'');
  await mutate('INSERT INTO "ProductCategory"("id","companyId","name") VALUES(\'native-report-category\',\'company\',\'Native report own category\')');
  for(const [id,price]of [['product',10],['zero',0]])await mutate('INSERT INTO "Product"("id","companyId","name","salePrice","vatRate","categoryId") VALUES($1,\'company\',$2,$3,20,\'native-report-category\')','native-report-'+id,'Native report '+id,price);
  for(const [id,company,store,at,total]of [['start','company','selected','2026-11-18T22:00:00',24],['sibling','company','sibling','2026-11-19T10:00:00',12],['before','company','selected','2026-11-18T21:59:59.999',900],['end','company','selected','2026-11-19T22:00:00',800],['foreign','foreign','foreign','2026-11-19T10:00:00',700]]){
   await mutate('INSERT INTO "Sale"("id","companyId","storeId","occurredAt","total","subtotal","customerId") VALUES($1,$2,$3,$4::timestamp,$5,$6,$7)','native-report-sale-'+id,company,store,at,total,total/1.2,id==='start'?'Customer-foreign':null);
   await mutate('INSERT INTO "SaleLine"("id","saleId","productId","description","quantity","unitPrice","lineTotal","vatRate") VALUES($1,$2,$3,\'Native report displayed description\',$4,12,$5,20)','native-report-line-'+id,'native-report-sale-'+id,company==='foreign'?'foreign-item':'native-report-product',id==='start'?2:1,total);
  }
  for(const [id,company,store,oldPrice,newPrice,at,product]of [['global','company',null,0,10,'2026-11-18T22:00:00','native-report-product'],['missing','company','selected',null,2,'2026-11-19T10:00:00','native-report-product'],['sibling','company','sibling',10,8,'2026-11-19T10:00:00','native-report-product'],['end','company',null,1,9,'2026-11-19T22:00:00','native-report-product'],['foreign','foreign','foreign',1,999,'2026-11-19T10:00:00','foreign-item']])await mutate('INSERT INTO "ProductPriceHistory"("id","companyId","productId","storeId","oldPrice","newPrice","createdAt","createdByName") VALUES($1,$2,$3,$4,$5,$6,$7::timestamp,\'Native displayed operator\')','native-report-price-'+id,company,product,store,oldPrice,newPrice,at);
  for(const [id,company,store]of [['bad','company','selected'],['zero','company','sibling'],['foreign','foreign','foreign']]){
   await mutate('INSERT INTO "DispatchNote"("id","companyId","storeId","documentNumber","recipientName","destinationAddress","createdByUserId","createdAt") VALUES($1,$2,$3,$4,\'Native recipient\',\'Native displayed address\',\'admin\',\'2026-11-19T10:00:00\')','native-report-note-'+id,company,store,'NATIVE-REPORT-'+id);
   await mutate('INSERT INTO "DispatchNoteLine"("id","dispatchNoteId","productId","description","quantity") VALUES($1,$2,$3,\'Native historical description\',2)','native-report-dispatch-line-'+id,'native-report-note-'+id,id==='zero'?'native-report-zero':'foreign-item');
  }
  for(const [id,company,store,supplier]of [['own','company','selected','Supplier-foreign'],['sibling','company','sibling','Supplier-company'],['foreign','foreign','foreign','Supplier-foreign']])await mutate('INSERT INTO "PurchaseDocument"("id","companyId","storeId","supplierId","documentNumber","documentDate","totalNet","totalVat","totalGross") VALUES($1,$2,$3,$4,$5,\'2026-11-19T10:00:00\',10,2,12)','native-report-purchase-'+id,company,store,supplier,'NATIVE-REPORT-'+id);
  const caps=['reports-price-changes.read','reports-departments.read','reports-documents.read','reports-delivery.read'];
  const owner={id:'company-owner',companyId:'company',role:'OWNER',tokenType:'BACKOFFICE_USER',sessionId:'company-owner-session',sessionVersion:0},created=await createStaffAccount(db,owner,{username:'company.reports.native',fullName:'Company Reports Native',pin:'987654',grants:[],companyCapabilities:caps});
  await mutate('INSERT INTO "UserSession"("id","userId","expiresAt") VALUES(\'native-company-reports-session\',$1,NOW()+INTERVAL \'1 hour\')',created.id);assert.equal((await db.$queryRawUnsafe('SELECT 1 FROM "BackofficeStaffGrant" WHERE "userId"=$1',created.id)).length,0);
  let afterRead=null;const readDb=new Proxy(db,{get(target,key){if(['$executeRaw','$executeRawUnsafe','$transaction'].includes(key))return()=>assert.fail('native report attempted write/bootstrap');const value=target[key];if(key==='$queryRaw')return async(...args)=>{assert.doesNotMatch(args[0].join('?'),/\b(?:INSERT|UPDATE|DELETE|CREATE|ALTER|FOR UPDATE)\b/);const rows=await value.apply(target,args);if(afterRead&&/FROM "(?:ProductPriceHistory|SaleLine|PurchaseDocument|DispatchNote)"/.test(args[0].join('?'))){const action=afterRead;afterRead=null;await action()}return rows};return typeof value==='function'?value.bind(target):value}});
  const source=await readFile(new URL('../../src/middleware/auth.js',import.meta.url),'utf8'),auth=new Function('prisma','jwt','assertCustomerDemoRuntimeClosed','enforceBackofficeStaff',source.slice(source.indexOf('export async function auth(')).replace('export async function auth','async function auth')+';return auth;')(readDb,jwt,assertCustomerDemoRuntimeClosed,enforceBackofficeStaff);
  const app=express();app.use(express.json());const index=await readFile(new URL('../../src/index.js',import.meta.url),'utf8'),start=index.indexOf('// Exact company reads precede'),end=index.indexOf('app.use("/api/management/vat-departments"',start);assert.ok(start>0&&end>start);new Function('app','auth','readStaffCompanyDirectory','prisma',index.slice(start,end))(app,auth,readStaffCompanyDirectory,readDb);app.use((_req,res)=>res.status(404).json({code:'UNEXPECTED_FALLTHROUGH'}));app.use((e,_req,res,_next)=>res.status(e.status||500).json({code:e.code}));server=app.listen(0,'127.0.0.1');await new Promise(resolve=>server.once('listening',resolve));
  const claims={companyId:'company',role:'EMPLOYEE',tokenType:'BACKOFFICE_USER',staffAccess:true,sessionVersion:0},token=jwt.sign({...claims,id:created.id,sessionId:'native-company-reports-session'},process.env.JWT_SECRET),storeToken=jwt.sign({...claims,id:'staff',sessionId:'workforce-native-session'},process.env.JWT_SECRET);
  const get=async(path,headers={},useStore=false)=>{const r=await fetch(`http://127.0.0.1:${server.address().port}/api/reports/${path}`,{headers:{authorization:'Bearer '+(useStore?storeToken:token),'x-backoffice-company-id':'company',...headers}});return {status:r.status,body:await r.json()}};
  const range='from=2026-11-19&to=2026-11-19';
  const price=await get('price-changes?'+range);assert.equal(price.status,200,JSON.stringify(price));assert.equal(price.body.items.length,3);const prices=Object.fromEntries(price.body.items.map(r=>[r.id,r]));assert.equal(prices['native-report-price-global'].difference,10);assert.equal(prices['native-report-price-global'].differencePercent,null);assert.equal(prices['native-report-price-missing'].incomplete,true);assert.equal(prices['native-report-price-missing'].difference,null);assert.equal(prices['native-report-price-sibling'].difference,-2);const filtered=await get('price-changes?'+range+'&storeId=selected');assert.equal(filtered.status,200);assert.equal(filtered.body.items.length,2);assert.ok(filtered.body.items.some(r=>r.storeId===null));
  const dept=await get('departments?'+range);assert.equal(dept.status,200,JSON.stringify(dept));assert.equal(dept.body.fiscal,false);assert.equal(dept.body.items.reduce((s,r)=>s+r.grossValue,0),36);assert.equal(dept.body.items.reduce((s,r)=>s+r.quantity,0),3);assert.equal(dept.body.items.reduce((s,r)=>s+r.netValue,0),30);const ownDept=await get('departments?'+range+'&storeId=selected');assert.equal(ownDept.body.items.reduce((s,r)=>s+r.grossValue,0),24);
  const docs=await get('documents?'+range);assert.equal(docs.status,200,JSON.stringify(docs));assert.equal(docs.body.fiscalSales,false);assert.equal(docs.body.items.length,4);assert.equal(docs.body.items.find(r=>r.id==='native-report-purchase-own').partyName,null);assert.equal(docs.body.items.find(r=>r.id==='native-report-sale-start').partyName,null);assert.equal(docs.body.items.find(r=>r.id==='native-report-sale-start').totalVat,0);assert.equal(docs.body.items.find(r=>r.id==='native-report-sale-start').totalNet,20);
  const delivery=await get('delivery?'+range);assert.equal(delivery.status,200,JSON.stringify(delivery));assert.equal(delivery.body.count,2);assert.equal(delivery.body.totalRetailValue,null);assert.equal(delivery.body.incomplete,true);assert.equal(delivery.body.items.find(r=>r.id==='native-report-note-zero').retailValue,0);assert.equal(delivery.body.items.find(r=>r.id==='native-report-note-zero').incomplete,false);
  const detail=await get('delivery/native-report-note-bad/lines');assert.equal(detail.status,200,JSON.stringify(detail));assert.equal(detail.body.totalRetailValue,null);assert.equal(detail.body.unavailableCount,1);const line=detail.body.items[0];assert.equal(line.productId,null);assert.equal(line.salePrice,null);assert.equal(line.vatRate,null);assert.equal(line.productUnavailable,true);assert.equal(line.description,'Native historical description');const zero=await get('delivery/native-report-note-zero/lines');assert.equal(zero.body.totalRetailValue,0);assert.equal(zero.body.incomplete,false);assert.equal((await get('delivery/native-report-note-foreign/lines')).status,404);
  for(const path of ['price-changes?'+range+'&storeId=foreign','delivery/native-report-note-bad/lines?'+range,'departments?'+range+'&q=x','documents?from=2026-02-30&to=2026-03-01','documents?'+range+'&from=2026-11-18'])assert.ok([400,403,404].includes((await get(path)).status));assert.equal((await get('documents?'+range,{'x-backoffice-store-id':'selected'})).status,403);assert.equal((await get('documents?'+range,{},true)).status,403);
  await mutate('UPDATE "CompanyModule" SET "active"=false WHERE "companyId"=\'company\' AND "moduleKey"=\'INVENTORY\'');for(const path of ['price-changes','departments','documents','delivery'])assert.equal((await get(path+'?'+range)).status,403);await mutate('UPDATE "CompanyModule" SET "active"=true WHERE "companyId"=\'company\' AND "moduleKey"=\'INVENTORY\'');
  afterRead=()=>mutate('UPDATE "BackofficeStaffAccount" SET "revision"="revision"+1 WHERE "userId"=$1',created.id);assert.equal((await get('price-changes?'+range)).status,403);afterRead=()=>mutate('UPDATE "BackofficeStaffAccount" SET "companyCapabilities"=\'[]\'::jsonb WHERE "userId"=$1',created.id);assert.equal((await get('delivery/native-report-note-bad/lines')).status,403);
 }finally{if(server){server.closeAllConnections();await new Promise(resolve=>server.close(resolve))}for(const key of keys){if(saved[key]===undefined)delete process.env[key];else process.env[key]=saved[key]}}
}
